@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : long
}

class PersonalAccount {}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + VisitCount : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

class FriendRequest {}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
PersonalAccount -- "*" FriendRequest
PersonalAccount "1" -- "*" Page : administers
PersonalAccount "0..*" -- "*" Page : hasPrivileges
BusinessAccount "1" -- "*" Page : administers
Page --|> AdvertisementPage
BusinessAccount "1" -- "*" AdvertisementPage

@enduml

